const stats = $input.item.json;
const s = stats.summary || {};
const lossRate = s.loss_rate || 0;
const totalPurchased = s.total_purchased || 0;
const totalDispatched = s.total_dispatched || 0;
const timeline = stats.timeline || [];
const anomalies = [];
let score = 0;

if (lossRate > 25) { anomalies.push({type:'LOSS_CRITICAL',severity:'HIGH',message:`Loss rate is ${lossRate}% — far above 10% threshold`}); score+=40; }
else if (lossRate > 15) { anomalies.push({type:'LOSS_HIGH',severity:'MEDIUM',message:`Loss rate is ${lossRate}% — above threshold`}); score+=20; }

const last2Days = timeline.slice(-2);
const recentActivity = last2Days.reduce((sum,d) => sum+(d.purchased||0)+(d.dispatched||0),0);
if (s.total_entries > 10 && recentActivity === 0) { anomalies.push({type:'NO_RECENT_ACTIVITY',severity:'MEDIUM',message:'No entries in last 48 hours — data may be stale'}); score+=25; }

if (totalPurchased > 1000) {
  const ratio = totalDispatched/totalPurchased;
  if (ratio < 0.5) { anomalies.push({type:'DISPATCH_BACKLOG',severity:'MEDIUM',message:`Only ${Math.round(ratio*100)}% of purchased material dispatched`}); score+=20; }
}

const today = timeline[timeline.length-1] || {};
const todayLossPct = today.purchased > 0 ? (today.loss/today.purchased*100) : 0;
if (todayLossPct > 30) { anomalies.push({type:'TODAY_LOSS_SPIKE',severity:'HIGH',message:`Today loss is ${todayLossPct.toFixed(1)}% of inflow`}); score+=35; }

const hasAlert = score >= 20;
const alertLevel = score >= 60 ? 'CRITICAL' : score >= 30 ? 'WARNING' : 'INFO';
return [{ json: { hasAlert, alertLevel, score, anomalies, stats: s } }];

const data = $input.item.json;
const anomalies = data.anomalies || [];
const level = data.alertLevel;
const s = data.stats || {};
const emoji = level==='CRITICAL'?'🔴':level==='WARNING'?'🟡':'🔵';
const now = new Date().toLocaleString('en-IN',{timeZone:'Asia/Kolkata'});
const anomalyLines = anomalies.map(a => {
  const sev = a.severity==='HIGH'?'❗':'⚠️';
  return `${sev} *${a.type.replace(/_/g,' ')}*
   ${a.message}`;
}).join('

');
const whatsappMessage = `${emoji} *TraceFlow Anomaly Alert*

*Level:* ${level}
*Time:* ${now} IST

*Detected:*
${anomalyLines}

*Loss Rate:* ${s.loss_rate||0}%
*Total Entries:* ${s.total_entries||0}`;
const emailSubject = `${emoji} TraceFlow ALERT — ${level} | ${anomalies.length} anomaly detected`;
const htmlEmail = `<div style='font-family:monospace;background:#0D0D0D;color:#E8DCC8;padding:32px'><h2 style='color:#F59E0B'>${emoji} ${level} ANOMALY ALERT</h2>${anomalies.map(a=>`<div style='border-left:3px solid #F87171;padding:12px;margin:8px 0;background:#141414'><b style='color:#F87171'>${a.type}</b><br>${a.message}</div>`).join('')}<p>Loss Rate: <b style='color:#F59E0B'>${s.loss_rate||0}%</b></p></div>`;
return [{ json: { whatsappMessage, htmlEmail, emailSubject, alertLevel: level, anomalyCount: anomalies.length } }];
